import assert from 'node:assert/strict'
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { chromium } from 'playwright'
import pixelmatch from 'pixelmatch'
import { PNG } from 'pngjs'
import { mockGetInfo, mockDeptTreeInPermission } from './home-v2-mocks.js'

// E2E_NAV_FIXTURE_ONLY_MARKER: this test and its auth token must never enter production dist.
const __dirname = path.dirname(fileURLToPath(import.meta.url))
const BASE_URL = process.env.E2E_BASE_URL || 'http://127.0.0.1:8101'
const API_PREFIX = '/api/v2.0'
const EXPECTED_HEIGHT = 110
const VIEWPORT = { width: 1920, height: 1110 }
const INTERACTION_VIEWPORT = { width: 1366, height: 768 }
const REFERENCE = path.join(__dirname, 'fixtures', 'navbar-reference.png')
const ARTIFACT_DIR = path.resolve(__dirname, '..', '..', 'artifacts', 'task2468-navbar-visual')
const ACTUAL = path.join(ARTIFACT_DIR, 'navbar-visual-1920.png')
const DIFF = path.join(ARTIFACT_DIR, 'navbar-diff-1920.png')
const NAV_TITLES = [
  '工作中心',
  '数据大屏',
  '行业管理',
  '项目管理',
  '业主自治',
  '共有资金',
  '阳光物业',
  '公共查询',
  '设施设备',
  '公共信息'
]

const menuRouters = NAV_TITLES.map((title, index) => ({
  name: `NavbarRoot${index}`,
  path: index === 0 ? '/index' : `/navbar-${index}`,
  hidden: false,
  component: 'Layout',
  meta: { title },
  children: [{
    name: `NavbarPage${index}`,
    path: 'index',
    component: 'home/index',
    meta: { title: `${title}页面`, icon: 'dashboard' }
  }]
}))

function jsonResponse(body, status = 200) {
  return { status, contentType: 'application/json', body: JSON.stringify(body) }
}

async function installMocks(context, { empty = false } = {}) {
  await context.route(`**${API_PREFIX}/**`, async (route) => {
    const pathname = new URL(route.request().url()).pathname
    if (pathname.includes('/system/platformConfig/getInfo')) {
      return route.fulfill(jsonResponse({
        code: 200,
        msg: 'ok',
        data: { region: '320500', platformName: '苏住房智慧物业管理平台' }
      }))
    }
    if (pathname.includes('/system/dept/treeInPermission')) {
      return route.fulfill(jsonResponse(mockDeptTreeInPermission))
    }
    if (pathname.includes('/menu/listRouters')) {
      return route.fulfill(jsonResponse({
        code: 200,
        msg: 'ok',
        data: empty ? [] : menuRouters
      }))
    }
    if (pathname.endsWith('/getInfo')) return route.fulfill(jsonResponse(mockGetInfo))
    if (pathname.includes('/secret') || pathname.includes('/captcha')) {
      return route.fulfill(jsonResponse({ code: 500, msg: 'skip sign in e2e' }))
    }
    return route.fulfill(jsonResponse({ code: 200, msg: 'ok', data: [], rows: [], total: 0 }))
  })

  await context.addInitScript(() => {
    const originalGet = sessionStorage.getItem.bind(sessionStorage)
    Object.defineProperty(sessionStorage, 'getItem', {
      configurable: true,
      value(key) {
        if (key === 'Admin-Token') return 'e2e-mock-token'
        return originalGet(key)
      }
    })
    localStorage.setItem('layout-setting', JSON.stringify({
      topNav: true,
      tagsView: true,
      fixedHeader: true,
      sidebarLogo: true
    }))
  })
}

async function openPage(browser, viewport, options) {
  const context = await browser.newContext({ viewport, deviceScaleFactor: 1 })
  await installMocks(context, options)
  const page = await context.newPage()
  await page.goto(`${BASE_URL}/#/index`, { waitUntil: 'domcontentloaded', timeout: 120000 })
  await page.locator('.navbar').waitFor({ state: 'visible', timeout: 60000 })
  return { context, page }
}

async function compareReference(actualPath) {
  const actual = PNG.sync.read(fs.readFileSync(actualPath))
  const reference = PNG.sync.read(fs.readFileSync(REFERENCE))
  if (actual.width !== reference.width || actual.height !== reference.height) {
    return { match: false, similarity: 0, reason: `size ${actual.width}x${actual.height} vs ${reference.width}x${reference.height}` }
  }
  const diff = new PNG({ width: actual.width, height: actual.height })
  const mismatched = pixelmatch(actual.data, reference.data, diff.data, actual.width, actual.height, {
    threshold: 0.1,
    includeAA: false
  })
  fs.writeFileSync(DIFF, PNG.sync.write(diff))
  const total = actual.width * actual.height
  const similarity = 1 - mismatched / total
  return { match: similarity >= 0.995, similarity, mismatched, total }
}

async function verifyReference(browser) {
  const { context, page } = await openPage(browser, VIEWPORT)
  try {
    await page.waitForFunction(
      (count) => document.querySelectorAll('.top-nav .nav-item').length === count,
      NAV_TITLES.length,
      { timeout: 60000 }
    )
    await page.addStyleTag({ content: '*, *::before, *::after { animation: none !important; transition: none !important; caret-color: transparent !important; }' })
    await page.waitForTimeout(300)
    fs.mkdirSync(ARTIFACT_DIR, { recursive: true })
    const box = await page.locator('.navbar').evaluate((element) => {
      const rect = element.getBoundingClientRect()
      return { width: Math.round(rect.width), height: Math.round(rect.height) }
    })
    await page.locator('.navbar').screenshot({ path: ACTUAL, animations: 'disabled' })
    console.log(`[navbar-visual] 1920 screenshot=${box.width}x${box.height}`)
    assert.equal(box.height, EXPECTED_HEIGHT, `navbar height must be ${EXPECTED_HEIGHT}px`)
    const comparison = await compareReference(ACTUAL)
    console.log(`[navbar-visual] similarity=${(comparison.similarity * 100).toFixed(3)}%`)
    assert.ok(comparison.match, `navbar screenshot mismatch: ${JSON.stringify(comparison)}; diff=${DIFF}`)
  } finally {
    await context.close()
  }
}

async function verifyOverflow(browser) {
  const { context, page } = await openPage(browser, INTERACTION_VIEWPORT)
  try {
    await page.waitForFunction(
      (count) => document.querySelectorAll('.top-nav .nav-item').length === count,
      NAV_TITLES.length,
      { timeout: 60000 }
    )
    const nav = page.locator('.nav-items-scroll')
    const left = page.locator('.top-nav-arrow[aria-label="向左查看更多菜单"]')
    const right = page.locator('.top-nav-arrow[aria-label="向右查看更多菜单"]')
    await page.waitForFunction(() => {
      const element = document.querySelector('.nav-items-scroll')
      return element && element.scrollWidth - element.clientWidth > 2
    }, null, { timeout: 10000 })
    assert.equal(await left.isDisabled(), true, 'left arrow starts at the beginning')
    assert.equal(await right.isDisabled(), false, 'right arrow is enabled when menus overflow')

    let rightClicks = 0
    while (!(await right.isDisabled()) && rightClicks < 30) {
      await right.click()
      rightClicks += 1
      await page.waitForTimeout(400)
    }
    assert.ok(rightClicks > 0, 'right arrow should scroll the menu')
    assert.equal(await right.isDisabled(), true, 'right arrow stops at the end')
    const end = await nav.evaluate((element) => ({
      left: element.scrollLeft,
      max: element.scrollWidth - element.clientWidth
    }))
    assert.ok(end.max - end.left <= 3, `menu reached right boundary: ${JSON.stringify(end)}`)

    const lastMenu = page.locator('.top-nav .nav-item').last()
    await lastMenu.click()
    await page.locator('.top-nav .nav-item.active').filter({ hasText: NAV_TITLES.at(-1) }).waitFor({ timeout: 10000 })

    let leftClicks = 0
    while (!(await left.isDisabled()) && leftClicks < 30) {
      await left.click()
      leftClicks += 1
      await page.waitForTimeout(400)
    }
    assert.ok(leftClicks > 0, 'left arrow should scroll the menu')
    assert.equal(await left.isDisabled(), true, 'left arrow stops at the beginning')
    const start = await nav.evaluate((element) => element.scrollLeft)
    assert.ok(start <= 3, `menu returned to left boundary: ${start}`)
    console.log(`[navbar-visual] overflow passed: right=${rightClicks}, left=${leftClicks}`)
  } finally {
    await context.close()
  }
}

async function verifyEmptyPermissions(browser) {
  const { context, page } = await openPage(browser, VIEWPORT, { empty: true })
  try {
    await page.waitForFunction(() => {
      const navbar = document.querySelector('.navbar')
      return navbar && document.querySelectorAll('.top-nav .nav-item').length === 0
    }, null, { timeout: 10000 })
    assert.equal(await page.locator('.top-nav-arrow').count(), 0, 'empty menu has no scroll arrows')
    console.log('[navbar-visual] empty permissions passed')
  } finally {
    await context.close()
  }
}

async function main() {
  assert.ok(fs.existsSync(REFERENCE), `missing Navbar reference fixture: ${REFERENCE}`)
  const browser = await chromium.launch({ headless: true })
  try {
    await verifyReference(browser)
    await verifyOverflow(browser)
    await verifyEmptyPermissions(browser)
  } finally {
    await browser.close()
  }
}

main().catch((error) => {
  console.error('[navbar-visual] failed', error)
  process.exitCode = 1
})
